<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Download, FileUp, Plus, RefreshCw } from 'lucide-vue-next'
import { api, apiError } from '../api/client'
import { fetchAllPages } from '../api/pagination'
import type { ApiResponse, Company, Receivable } from '../types'
import PageHeader from '../components/PageHeader.vue'
import SectionTabs from '../components/SectionTabs.vue'
import DrawerPanel from '../components/DrawerPanel.vue'
import InlineAlert from '../components/InlineAlert.vue'
import StatusBadge from '../components/StatusBadge.vue'
import EmptyState from '../components/EmptyState.vue'
interface Agreement{id:string;company_id:string;name:string;provider:string;cnab_layout:string;is_active:boolean}
interface Remittance{id:string;company_id:string;bank_agreement_id:string;sequence:number;layout:string;status:string;sha256:string;record_count:number;total_amount:string;generated_at:string}
interface Return{id:string;company_id:string;bank_code:string;layout:string;filename:string;sha256:string;status:string;event_count:number;summary:Record<string,unknown>;processed_at?:string;last_error?:string;created_at:string}
interface Event{id:string;return_id:string;receivable_id?:string;charge_id?:string;occurrence_code:string;occurrence_description:string;our_number?:string;amount?:string;occurrence_date?:string;status:string;created_at:string}
const tab=ref('remittances'),agreements=ref<Agreement[]>([]),companies=ref<Company[]>([]),receivables=ref<Receivable[]>([]),remittances=ref<Remittance[]>([]),returns=ref<Return[]>([]),events=ref<Event[]>([]),drawer=ref(false),returnDrawer=ref(false),error=ref(''),success=ref(''),file=ref<File|null>(null),downloading=ref('')
const form=reactive({bank_agreement_id:'',receivable_ids:[] as string[],company_id:''})
const money=(v:string)=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const companyName=(id:string)=>companies.value.find(x=>x.id===id)?.trade_name||companies.value.find(x=>x.id===id)?.legal_name||'Empresa'
const summaryText=(item:Return)=>{const s=item.summary||{};const parts=[['Liquidado',s.liquidated],['Associado',s.matched],['Não associado',s.unmatched]].filter(([,v])=>Number(v||0)>0).map(([k,v])=>`${k}: ${v}`);return parts.join(' · ')||`${item.event_count} ocorrência(s)`}
async function load(){error.value='';try{const [a,c,r,rm,rt,e]=await Promise.all([api.get<ApiResponse<Agreement[]>>('/v1/bank-agreements'),api.get<ApiResponse<Company[]>>('/v1/companies'),fetchAllPages<Receivable>('/v1/receivables'),api.get<ApiResponse<Remittance[]>>('/v1/cnab/remittances'),api.get<ApiResponse<Return[]>>('/v1/cnab/returns'),api.get<ApiResponse<Event[]>>('/v1/cnab/events')]);agreements.value=a.data.data;companies.value=c.data.data;receivables.value=r;remittances.value=rm.data.data;returns.value=rt.data.data;events.value=e.data.data}catch(e){error.value=apiError(e)}}
function openRemittance(){form.bank_agreement_id=agreements.value[0]?.id||'';form.receivable_ids=[];drawer.value=true}
async function downloadRemittance(item:{id:string;sequence?:number;layout?:string}){downloading.value=item.id;error.value='';try{const response=await api.get(`/v1/cnab/remittances/${item.id}/download`,{responseType:'blob'});const href=URL.createObjectURL(response.data);const anchor=document.createElement('a');anchor.href=href;anchor.download=`REM-${String(item.sequence||1).padStart(6,'0')}-CNAB${item.layout||'240'}.REM`;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(href)}catch(e){error.value=apiError(e)}finally{downloading.value=''}}
async function generate(){error.value='';try{const created=(await api.post<ApiResponse<{id:string;sequence:number;layout?:string}>>('/v1/cnab/remittances',{bank_agreement_id:form.bank_agreement_id,receivable_ids:form.receivable_ids})).data.data;drawer.value=false;success.value='Remessa CNAB gerada com sucesso.';await load();await downloadRemittance({id:created.id,sequence:created.sequence,layout:created.layout||agreements.value.find(x=>x.id===form.bank_agreement_id)?.cnab_layout})}catch(e){error.value=apiError(e)}}
function openReturn(){form.company_id=agreements.value[0]?.company_id||companies.value[0]?.id||'';file.value=null;returnDrawer.value=true}
async function upload(){if(!file.value)return;const data=new FormData();data.append('file',file.value);error.value='';try{await api.post('/v1/cnab/returns',data,{params:{company_id:form.company_id},headers:{'Content-Type':'multipart/form-data'}});returnDrawer.value=false;success.value='Retorno processado e aplicado.';await load()}catch(e){error.value=apiError(e)}}
onMounted(load)
</script>
<template><PageHeader title="CNAB 240 e 400" subtitle="Remessas, retornos e ocorrências bancárias em um único lugar."><button class="btn-secondary" @click="load"><RefreshCw :size="18"/>Atualizar</button><button class="btn-secondary" @click="openReturn"><FileUp :size="18"/>Importar retorno</button><button class="btn-primary" @click="openRemittance"><Plus :size="18"/>Gerar remessa</button></PageHeader><InlineAlert :message="error" @dismiss="error=''"/><InlineAlert :message="success" type="success" @dismiss="success=''"/><SectionTabs v-model="tab" :items="[{key:'remittances',label:'Remessas',count:remittances.length},{key:'returns',label:'Retornos',count:returns.length},{key:'events',label:'Ocorrências',count:events.length}]"/><div v-if="tab==='remittances'" class="table-wrap"><table class="table"><thead><tr><th>Sequência</th><th>Convênio</th><th>Layout</th><th>Títulos</th><th>Total</th><th>Status</th><th>Gerada</th><th>Arquivo</th></tr></thead><tbody><tr v-for="item in remittances" :key="item.id" class="border-t border-slate-100"><td class="font-mono font-semibold">{{String(item.sequence).padStart(6,'0')}}</td><td>{{agreements.find(x=>x.id===item.bank_agreement_id)?.name||'Convênio'}}</td><td>CNAB {{item.layout}}</td><td>{{item.record_count}}</td><td class="font-bold">{{money(item.total_amount)}}</td><td><StatusBadge :status="item.status"/></td><td>{{new Date(item.generated_at).toLocaleString('pt-BR')}}</td><td><button class="btn-secondary px-3 py-2" :disabled="downloading===item.id" @click="downloadRemittance(item)"><Download :size="15"/>{{downloading===item.id?'Baixando…':'Baixar'}}</button></td></tr></tbody></table><EmptyState v-if="!remittances.length" title="Nenhuma remessa"/></div><div v-else-if="tab==='returns'" class="table-wrap"><table class="table"><thead><tr><th>Arquivo</th><th>Empresa</th><th>Banco</th><th>Layout</th><th>Eventos</th><th>Resultado</th><th>Status</th></tr></thead><tbody><tr v-for="item in returns" :key="item.id" class="border-t border-slate-100"><td><p class="font-semibold">{{item.filename}}</p></td><td>{{companyName(item.company_id)}}</td><td>{{item.bank_code}}</td><td>CNAB {{item.layout}}</td><td>{{item.event_count}}</td><td class="text-xs text-slate-500">{{summaryText(item)}}</td><td><StatusBadge :status="item.status"/><p v-if="item.last_error" class="text-xs text-rose-600">Falha ao processar parte do retorno.</p></td></tr></tbody></table></div><div v-else class="table-wrap"><table class="table"><thead><tr><th>Ocorrência</th><th>Nosso número</th><th>Recebível</th><th>Valor</th><th>Data</th><th>Status</th></tr></thead><tbody><tr v-for="item in events" :key="item.id" class="border-t border-slate-100"><td><span class="badge bg-slate-100 text-slate-700">{{item.occurrence_code}}</span><p class="mt-1 text-xs">{{item.occurrence_description}}</p></td><td class="font-mono text-xs">{{item.our_number||'—'}}</td><td class="text-xs">{{item.receivable_id?'Associado':'Não associado'}}</td><td>{{item.amount?money(item.amount):'—'}}</td><td>{{item.occurrence_date?new Date(item.occurrence_date+'T00:00:00').toLocaleDateString('pt-BR'):'—'}}</td><td><StatusBadge :status="item.status"/></td></tr></tbody></table></div><DrawerPanel :open="drawer" title="Gerar remessa CNAB" width="lg" @close="drawer=false"><form class="space-y-4" @submit.prevent="generate"><div><label class="label">Convênio</label><select v-model="form.bank_agreement_id" class="select" required><option v-for="a in agreements.filter(x=>x.is_active)" :key="a.id" :value="a.id">{{a.name}} · CNAB {{a.cnab_layout}}</option></select></div><div><label class="label">Títulos</label><div class="scroll-clean max-h-80 space-y-1 overflow-auto rounded-xl border border-slate-200 p-2"><label v-for="r in receivables.filter(x=>['OPEN','REGISTERED'].includes(x.status)&&x.company_id===agreements.find(a=>a.id===form.bank_agreement_id)?.company_id)" :key="r.id" class="flex items-center gap-3 rounded-lg p-2 hover:bg-slate-50"><input v-model="form.receivable_ids" type="checkbox" :value="r.id"/><span class="min-w-0 flex-1"><span class="block truncate text-sm font-medium">{{r.document_number}} · {{r.description}}</span><span class="text-xs text-slate-400">Vence {{new Date(r.due_date+'T00:00:00').toLocaleDateString('pt-BR')}}</span></span><strong>{{money(r.balance)}}</strong></label></div></div><div class="flex justify-end gap-2"><button type="button" class="btn-secondary" @click="drawer=false">Cancelar</button><button class="btn-primary" :disabled="!form.receivable_ids.length"><Download :size="16"/>Gerar e baixar</button></div></form></DrawerPanel><DrawerPanel :open="returnDrawer" title="Importar retorno CNAB" width="md" @close="returnDrawer=false"><form class="space-y-4" @submit.prevent="upload"><div><label class="label">Empresa</label><select v-model="form.company_id" class="select" required><option v-for="company in companies" :key="company.id" :value="company.id">{{company.trade_name||company.legal_name}}</option></select></div><div><label class="label">Arquivo de retorno</label><input type="file" class="input" accept=".ret,.txt,.cnab" required @change="file=($event.target as HTMLInputElement).files?.[0]||null"/></div><div class="rounded-xl bg-sky-50 p-3 text-xs text-sky-800">O sistema identifica automaticamente o layout e aplica as ocorrências aos títulos correspondentes.</div><div class="flex justify-end gap-2"><button type="button" class="btn-secondary" @click="returnDrawer=false">Cancelar</button><button class="btn-primary">Processar retorno</button></div></form></DrawerPanel></template>
